import pathlib,json,statistics,math
from PIL import Image,ImageDraw,ImageFont
R=pathlib.Path('../research/overnight-study/research');A=R/'audio-plots';A.mkdir(exist_ok=True);d=json.loads((R/'audio-crosscheck.json').read_text());cs=d['charts'];font=ImageFont.truetype('/System/Library/Fonts/Hiragino Sans GB.ttc',14)
text=['# Digital music cross-check','','All 46 unique songs with full audio were analyzed, covering 53 primary charts and six supplementary charts. No audio errors. This is structural evidence from audio and source charts, not automatic instrument identification, meter confirmation, human listening, or a quality score.','',d['method'],'','Median chart tap→nearest flux peak distance across all59 charts: %.2fms; range %.2f–%.2fms. Eight-second note-count/RMS Pearson correlation median %.3f, and note-count/mean-flux correlation median %.3f. These comparisons are descriptive and are inflated by coarse section structure; high correlation is not proof of correct charting.'%(statistics.median(c['timing_by_note_type']['1']['median_nearest_peak_ms'] for c in cs),min(c['timing_by_note_type']['1']['median_nearest_peak_ms'] for c in cs),max(c['timing_by_note_type']['1']['median_nearest_peak_ms'] for c in cs),statistics.median(c['section_note_density_vs_rms_correlation'] for c in cs),statistics.median(c['section_note_density_vs_flux_correlation'] for c in cs)),'','Onset detectors miss smooth attacks and weak/overlapping parts, and add peaks for sounds a chart may intentionally omit. Sustained Hold duration is compared with section energy separately from head onset timing. Drag contours can be distributed between attacks; they should never be forced onto every detected peak. Every source chart offset is included in the music comparison.','', '|Chart|Tap distinct onsets|Median peak gap ms|90th percentile ms|Within35ms|Density/RMS r|','|---|---|---|---|---|---|']
html=[]
for i,c in enumerate(cs,1):
 t=c['timing_by_note_type']['1'];text.append('|%s %s|%d|%.2f|%.2f|%.1f%%|%.3f|'%(c['title'],c['difficulty'],t['distinct_onsets'],t['median_nearest_peak_ms'],t['p90_nearest_peak_ms'],t['fraction_within_35ms']*100,c['section_note_density_vs_rms_correlation']))
 rows=c['sections'];W,H=1200,380;im=Image.new('RGB',(W,H),'#10131d');dr=ImageDraw.Draw(im);dr.text((15,10),f"{c['title']} {c['difficulty']} — chart offset {c['chart_offset_seconds']}s; independent normalization of each trace",font=font,fill='white');ox,oy,pw,ph=55,65,1100,220
 for j in range(5):y=oy+j*ph/4;dr.line((ox,y,ox+pw,y),fill='#354050');dr.text((15,y-5),str(round(1-j/4,2)),font=font,fill='#9ba9be')
 for key,col,label in [('notes','#62d7ff','Note objects'),('rms','#efb050','Audio RMS'),('flux_mean','#f37f99','Positive spectral flux'),('active_hold_seconds','#ae98ef','Hold contact seconds')]:
  vals=[r[key] for r in rows];maxv=max(vals) or 1;pts=[(ox+(r['start']+4)/(rows[-1]['end'])*pw,oy+ph*(1-v/maxv)) for r,v in zip(rows,vals)];dr.line(pts,fill=col,width=2);dr.text((ox+list(['notes','rms','flux_mean','active_hold_seconds']).index(key)*265,37),label,font=font,fill=col)
 for sec in range(0,rows[-1]['end'],20):x=ox+sec/rows[-1]['end']*pw;dr.text((x,oy+ph+5),str(sec)+'s',font=font,fill='#9ba9be')
 dr.text((15,335),'8s bins in audio time. Curves describe section contrast; a low note/energy match can be deliberate phrasing, not an error.',font=font,fill='#9ba9be');im.save(A/f'{i:02d}.png');html.append(f'<details><summary>{c["title"]} {c["difficulty"]}</summary><img src="audio-plots/{i:02d}.png"></details>')
text+=['','## Interpreting deviations','','The actual per-type distributions and ±30/60/100ms sensitivity are in `audio-crosscheck.json`. Compare those with the source grid and listen before adjusting any offset. The tested offsets are sensitivity probes, not a fitted correction.','', 'Examples: Cycle of Redemption IN570 distinct Tap onsets median4.90ms and92.63% within35ms; its sustain/rest structure still needs listening, not peak matching. Verrückt IN median14.67ms and68.42% within35ms despite strong section-density/RMS r=.911; this is a reminder that timing detectors depend on timbre and fast detail. Chronostasis uses a nonzero0.06s chart offset and has median9.00ms; evaluating it with offset0 would compare the wrong temporal origin.']
(R/'audio-crosscheck.md').write_text('\n'.join(text));(R/'audio-crosscheck.html').write_text('<!doctype html><meta charset="utf-8"><style>body{background:#10131d;color:white;font-family:sans-serif}img{max-width:100%}summary{padding:8px;cursor:pointer}</style><h1>Audio/chart structural comparison</h1><p>Each curve independently normalized in8s bins; chart offsets included. This is descriptive evidence, not a beat detector or musical correctness score.</p>'+''.join(html));print('created59plots')
